import{_ as t,c as e,a,aS as l}from"./chunks/framework.BB9D2qGO.js";const g=JSON.parse('{"title":"数据库","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/数据库.md","filePath":"note/back-end/mianshi/数据库.md","lastUpdated":1756786143000}'),d={name:"note/back-end/mianshi/数据库.md"},i=l('<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><h2 id="事务的隔离级别" tabindex="-1">事务的隔离级别 <a class="header-anchor" href="#事务的隔离级别" aria-label="Permalink to &quot;事务的隔离级别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">隔离级别</th><th style="text-align:left;">脏读</th><th style="text-align:left;">不可重复读</th><th style="text-align:left;">幻读</th></tr></thead><tbody><tr><td style="text-align:left;">读未提交（Read uncommitted）</td><td style="text-align:left;">×(未解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">读已提交（Read committed）</td><td style="text-align:left;">√(解决)</td><td style="text-align:left;">×</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可重复读（Repeatable read）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">×</td></tr><tr><td style="text-align:left;">可串行化（Serializable）</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td><td style="text-align:left;">√</td></tr></tbody></table><p>脏读: 读取到未提交的事务数据</p><p>不可重复读: 同一事务内多次读取同一行数据时，因其他事务修改该行数据并提交，导致读取结果不一致。例如：事务A两次读取用户年龄，第一次为20岁，第二次因事务B修改变成22岁。‌</p><p>幻读‌：同一事务内多次执行相同范围查询时，因其他事务插入或删除符合条件的数据，导致结果集数量不一致。例如：事务A统计年龄&gt;20的用户数，第一次为3条，第二次因事务B插入新用户变为4条。‌</p><h2 id="mvcc" tabindex="-1">MVCC <a class="header-anchor" href="#mvcc" aria-label="Permalink to &quot;MVCC&quot;">​</a></h2><p>MVCC叫多版本并发控制，是一种通过保存数据的历史版本来实现并发访问的技术。它的核心目的是让读操作和写操作可以互不阻塞，从而提升数据库的并发性能</p><ul><li>mvcc的核心是快照读</li><li>undo log 是历史版本的支撑</li><li>readview 决定谁能看到那个版本</li></ul>',9),n=[i];function s(r,o,c,h,f,_){return a(),e("div",null,n)}const m=t(d,[["render",s]]);export{g as __pageData,m as default};
